package com.bookstore.bike.security;
import com.bookstore.bike.repo.UserRepository; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.util.*;
@Configuration @EnableWebSecurity public class SecurityConfig {
 @Value("${campusride.jwt.secret}") String secret;
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(UserRepository repo){return email->repo.findByEmail(email).map(u->User.withUsername(u.getEmail()).password(u.getPassword()).authorities("ROLE_"+u.getRole()).disabled(!u.isActive()).build()).orElseThrow(()->new UsernameNotFoundException(email));}
 @Bean SecurityFilterChain filter(HttpSecurity http) throws Exception {http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/h2-console/**").permitAll().requestMatchers(HttpMethod.GET,"/api/bikes","/api/bikes/*").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(new JwtFilter(secret),UsernamePasswordAuthenticationFilter.class).headers(h->h.frameOptions(f->f.sameOrigin())); return http.build();}
 static class JwtFilter extends OncePerRequestFilter {final SecretKey key; JwtFilter(String s){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer "))try{Claims cl=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload(); var auth=new UsernamePasswordAuthenticationToken(cl.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+cl.get("role")))); SecurityContextHolder.getContext().setAuthentication(auth);}catch(JwtException ignored){} c.doFilter(r,p);}}
}
